// Home Express gift bundles reference, with independent editable product layers.
let homeBackImage=null,homeBackBackground=null;
const homeBackGroups=[
 {name:'Christmas Gift Bundles',x:18,y:800,w:1244,h:275,photo:150,lines:2,edges:[18,254,509,766,1017,1262],items:[['TUPPERWARE',199],['FOOD KEEPR 3PCS',219],['FOOD KEEPER 2PCS',149],['PITCHER',79],['PLASTIC TUPPERWARE',105]]},
 {name:'Best Seller This Season',x:18,y:1158,w:1244,h:268,photo:143,lines:2,edges:[18,265,514,755,1004,1262],items:[['CEILING FAN',259],['STORAGE BOX',899],['PORTABLE STOVE',599],['KITCHEN DRAWER',1399],['PLASTIC CHAIR',279]]},
 {name:'Top Product',x:18,y:1510,w:1244,h:243,photo:133,lines:2,edges:[18,265,513,759,1004,1262],items:[['DINING TABLE',899],['SEWING KIT',79],['FLOORMAT',115],['SPEAKER',899],['RATTAN DRAWER',1099]]}
];
function homeBackState(){if(!state.homeBack)state.homeBack={designVersion:1,slots:homeBackGroups.flatMap((g,group)=>g.items.map((_,i)=>({productId:`home-back1-${group}-${i}`,group,image:null,discountPercent:0})))};return state.homeBack}
function homeBackCard(index){const slot=homeBackState().slots[index],g=homeBackGroups[slot.group],siblings=homeBackState().slots.filter(s=>s.group===slot.group),i=siblings.indexOf(slot);return {...g,x:siblings.length===g.items.length?g.edges[i]:g.x+i*g.w/siblings.length,w:siblings.length===g.items.length?g.edges[i+1]-g.edges[i]:g.w/siblings.length}}
async function initHomeBack(){try{
 const original=await loadCanvasImage(HOME_BACK_ORIGINAL_ART);homeBackImage=await loadCanvasImage(HOME_BACK_ART);
 // Preserve the approved layout and QR from the original; enhance only the product photo layers.
 homeBackBackground=productFreeArtwork(original,1280,1924,[...homeBackGroups.map(g=>[g.x,g.y,g.w,g.h]),[800,780,184,23],[1025,786,225,17],[802,1107,170,56],[1020,1120,228,42],[1083,1483,106,31],[799,1500,153,14]]);
 const crops=[[[46,804,201,137],[270,788,183,160],[545,787,185,161],[807,786,161,160],[1037,790,208,139]],[[47,1161,178,135],[270,1171,240,99],[536,1160,201,116],[817,1110,130,187],[1025,1123,220,171]],[[28,1515,198,127],[273,1525,234,101],[532,1509,219,127],[803,1501,147,136],[1086,1486,94,145]]];
 homeBackGroups.forEach((g,group)=>g.items.forEach(([name,price],i)=>{
  const id=`home-back1-${group}-${i}`,existing=state.products.find(p=>p.id===id);
  if(state.deletedProductIds?.includes(id))return;
  const trimRibbon=group===0&&(i===1||i===2);
  if(existing&&!trimRibbon)return;
  const [x,y,w,h]=crops[group][i],sx=homeBackImage.naturalWidth/1280,sy=homeBackImage.naturalHeight/1924;
  const crop=(top,height)=>{const c=document.createElement('canvas');c.width=Math.round(w*sx);c.height=Math.round(height*sy);const ctx=c.getContext('2d');ctx.imageSmoothingQuality='high';ctx.drawImage(homeBackImage,x*sx,top*sy,w*sx,height*sy,0,0,c.width,c.height);return c.toDataURL('image/png')};
  const image=trimRibbon?crop(804,h-(804-y)):crop(y,h);
  if(existing){if(existing.image===crop(y,h))existing.image=image;return}
  state.products.push({id,templateId:'home-back',name,price,code:`HOME-BACK-${group+1}-${i+1}`,image});
 }));homeBackState();renderAll();save();
 }catch(e){console.error(e);showNotice('Could not load Home Express-Back. Reload to try again.')}}
async function homeBackCanvas({width=1650,height=2550}={}){
 await document.fonts.load('800 20px Outfit');if(!homeBackBackground)throw Error('Home Express-Back artwork is loading');const c=document.createElement('canvas');c.width=width;c.height=height;const ctx=c.getContext('2d');ctx.imageSmoothingQuality='high';ctx.scale(width/1280,height/1924);ctx.drawImage(homeBackBackground,0,0,1280,1924);
 const store=state.poster.store||'HOMEEXPRESS';if(store.replace(/\s/g,'').toUpperCase()!=='HOMEEXPRESS'){ctx.fillStyle='#ffffff';ctx.fillRect(205,22,475,85);ctx.fillStyle='#063373';ctx.textAlign='left';pesoText(ctx,store,212,91,460,64,800)}
 const slots=homeBackState().slots,images=await Promise.all(slots.map(async slot=>{try{return await loadCanvasImage(slot.image||productFor(slot)?.image||svgThumb('+','#fffdf6'))}catch{return null}}));
 slots.forEach((slot,index)=>{
  const b=homeBackCard(index),p=productFor(slot),im=images[index];
  const discount=Math.round(independentDiscount(slot)*100)/100;
  const nameSize=24*textScale('name',slot),lineHeight=nameSize*1.05,priceSize=49*textScale('sale',slot),originalSize=priceSize*.4*textScale('original',slot);
  const originalBaseline=b.y+b.h-(slot.group===2?14:18);
  const priceBaseline=p&&discount>0?originalBaseline-originalSize*1.05-6:b.y+b.h-(slot.group===2?30:46);
  ctx.save();ctx.beginPath();ctx.rect(b.x,b.y,b.w,b.h);ctx.clip();ctx.fillStyle='#fffdf3';ctx.fillRect(b.x,b.y,b.w,b.h);
  ctx.font=`700 ${nameSize}px Outfit`;
  const lines=[''];for(const word of (p?.name||'Choose a product').split(/\s+/)){
   const i=lines.length-1,next=(lines[i]+' '+word).trim();
   if(ctx.measureText(next).width>b.w-16&&lines[i]&&lines.length<b.lines)lines.push(word);else lines[i]=next;
  }
  // Anchor the name block above the price, including room for letter descenders.
  const lastNameBaseline=priceBaseline-priceSize*.82-10-nameSize*.22;
  const firstNameBaseline=lastNameBaseline-(lines.length-1)*lineHeight;
  const photoH=Math.max(1,Math.min(b.photo,firstNameBaseline-nameSize-b.y-8));
  if(im){const scale=Math.min((b.w-10)/im.width,photoH/im.height);ctx.drawImage(im,b.x+(b.w-im.width*scale)/2,b.y+(photoH-im.height*scale)/2,im.width*scale,im.height*scale)}
  if(p&&discount>0){
   const badgeR=Math.max(16,Math.min(30,b.w*.17,photoH*.52)),cx=b.x+badgeR+5,cy=b.y+badgeR+5;
   ctx.save();ctx.fillStyle='#df1830';ctx.beginPath();
   const bumps=12,steps=bumps*8;
   for(let i=0;i<=steps;i++){const t=i/steps*Math.PI*2,rr=badgeR*(1+.14*Math.cos(bumps*t)),x=cx+rr*Math.cos(t),y=cy+rr*Math.sin(t);if(i)ctx.lineTo(x,y);else ctx.moveTo(x,y)}
   ctx.closePath();ctx.fill();
   ctx.textAlign='center';ctx.fillStyle='#ffdf22';
   pesoText(ctx,discount+'%',cx,cy-badgeR*.08,badgeR*1.55,badgeR*.78*textScale('discount',slot),800,.9);
   pesoText(ctx,'OFF',cx,cy+badgeR*.62,badgeR*1.45,badgeR*.52*textScale('discount',slot),800);
   ctx.restore();
  }
  ctx.strokeStyle='#e5e1d0';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(b.x+b.w-1,b.y+5);ctx.lineTo(b.x+b.w-1,b.y+b.h-4);ctx.stroke();
  ctx.textAlign='center';ctx.fillStyle='#111';
  lines.forEach((line,i)=>pesoText(ctx,line,b.x+b.w/2,firstNameBaseline+i*lineHeight,b.w-16,nameSize,700,.9));
  if(p){
   const number=new Intl.NumberFormat('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2}).format(salePrice(p,slot)),symbolSize=priceSize*.57;
   ctx.font=`800 ${symbolSize}px Arial, sans-serif`;const symbolWidth=ctx.measureText('\u20b1').width;
   ctx.font=`800 ${priceSize}px Outfit`;const numberWidth=Math.min(b.w-symbolWidth-18,ctx.measureText(number).width),left=b.x+(b.w-numberWidth-symbolWidth-2)/2;
   ctx.textAlign='left';ctx.fillStyle='#ed0015';ctx.font=`800 ${symbolSize}px Arial, sans-serif`;ctx.fillText('\u20b1',left,priceBaseline-4);
   pesoText(ctx,number,left+symbolWidth+2,priceBaseline,numberWidth,priceSize,800);
   if(discount>0){
    const originalText='\u20b1'+new Intl.NumberFormat('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2}).format(p.price);
    ctx.textAlign='center';ctx.fillStyle='#111';
    const drawnW=pesoText(ctx,originalText,b.x+b.w/2,originalBaseline,b.w-20,originalSize,700);
    ctx.fillRect(b.x+b.w/2-drawnW/2,originalBaseline-originalSize*.42,drawnW,1.3);
   }
  }else{ctx.textAlign='center';ctx.fillStyle='#ed0015';pesoText(ctx,'Add item',b.x+b.w/2,priceBaseline,b.w-20,priceSize,800)}
  ctx.restore();
 });return c;
}

const HOME_BACK_ART='data:image/png;base64,';

const HOME_BACK_ORIGINAL_ART='data:image/jpeg;base64,';
